INSERT INTO public.quiz_questions (unit_id, question, options, correct_answer, explanation) VALUES
  (1, 'Which statement about the Python interpreter is true?', '["It converts the whole program to machine code before running","It executes the code line by line as it runs","It only works inside a web browser","It requires a separate compiler to be installed"]'::jsonb, 'It executes the code line by line as it runs', 'Python is interpreted: the interpreter reads and executes your code as it goes, which is why you can test short snippets quickly.'),
  (1, 'Which of these is NOT a common use of Python?', '["Data science and machine learning","Web development","Writing device drivers for an operating system","Automating repetitive tasks"]'::jsonb, 'Writing device drivers for an operating system', 'Device drivers need low-level memory control and are written in C or Rust. Python is used for the other three every day.'),
  (2, 'What does type() tell you about a variable?', '["How much memory it uses","The kind of object it currently refers to","Whether the variable is a constant","How many times it has been assigned"]'::jsonb, 'The kind of object it currently refers to', 'Python is dynamically typed: a name refers to an object, and type() reports what kind of object that currently is.'),
  (2, 'Why does input() often need int() around it?', '["input() is too slow for numbers","input() always returns text, even when the user types digits","int() makes the program run faster","input() cannot read numbers at all"]'::jsonb, 'input() always returns text, even when the user types digits', 'input() always returns a string. Adding ''5'' and ''3'' gives ''53'', so you convert with int() before doing arithmetic.'),
  (3, 'What does 17 % 5 evaluate to?', '["2","3","3.4","12"]'::jsonb, '2', '% is the modulus operator: it gives the remainder. 17 divided by 5 is 3 remainder 2.'),
  (3, 'What does 17 // 5 evaluate to?', '["3.4","3","2","4"]'::jsonb, '3', '// is floor division: it divides and throws away the fractional part, giving 3.'),
  (3, 'Which operator checks whether two values are equal?', '["=","==","=>","==="]'::jsonb, '==', 'A single = assigns a value. == compares. Mixing them up is one of the most common beginner errors.'),
  (3, 'What does (10 > 5 and 3 > 7) evaluate to?', '["True","False","10","An error"]'::jsonb, 'False', '''and'' needs both sides to be True. 10 > 5 is True but 3 > 7 is False, so the whole expression is False.'),
  (3, 'What does "py" in "python" return?', '["True","False","0","''py''"]'::jsonb, 'True', '''in'' is the membership operator. It checks whether one sequence appears inside another, and returns True or False.'),
  (4, 'When does the else block run?', '["Always, after the if block","Only when the if condition is False","Only when the if condition is True","Only if there is no elif"]'::jsonb, 'Only when the if condition is False', 'else is the fallback: it runs only when the if condition (and any elif conditions) were all False.'),
  (4, 'Which of these values is falsy in Python?', '["''False''","[0]","0","''0''"]'::jsonb, '0', 'The number 0 is falsy. A non-empty string like ''False'' or ''0'', and a list containing something, are all truthy.'),
  (4, 'What is elif short for?', '["end if","else if","element if","evaluate if"]'::jsonb, 'else if', 'elif lets you test another condition when the previous one failed, without nesting a whole new if inside the else.'),
  (4, 'How does Python know which lines belong inside an if block?', '["Curly braces { }","The indentation","A semicolon at the end","The ''end'' keyword"]'::jsonb, 'The indentation', 'Indentation defines blocks in Python. This is why an inconsistent indent raises an IndentationError.'),
  (4, 'What happens if you write ''if x = 5:''?', '["It checks whether x equals 5","It sets x to 5 and then checks it","It raises a SyntaxError","It always evaluates to True"]'::jsonb, 'It raises a SyntaxError', 'Assignment is not allowed in an if condition. Python raises a SyntaxError, which is a useful guard against a common bug.'),
  (5, 'What does range(1, 5) produce?', '["1, 2, 3, 4, 5","1, 2, 3, 4","0, 1, 2, 3, 4","1, 5"]'::jsonb, '1, 2, 3, 4', 'range stops before the end value. range(1, 5) gives 1, 2, 3, 4 - four numbers, not five.'),
  (5, 'What does break do inside a loop?', '["Skips to the next iteration","Exits the loop immediately","Restarts the loop from the beginning","Pauses the program"]'::jsonb, 'Exits the loop immediately', 'break leaves the loop entirely. continue is the one that skips to the next iteration.'),
  (5, 'When is a while loop a better choice than a for loop?', '["When you know exactly how many times to repeat","When you are looping over a list","When you repeat until a condition changes and do not know the count","While loops are always better"]'::jsonb, 'When you repeat until a condition changes and do not know the count', 'for is for a known sequence. while is for ''keep going until something becomes true'' - like waiting for valid input.'),
  (5, 'What causes an infinite loop in ''while count < 5:''?', '["Using < instead of <=","Forgetting to change count inside the loop","Starting count at 0","Putting a print inside the loop"]'::jsonb, 'Forgetting to change count inside the loop', 'If nothing inside the loop moves count towards 5, the condition never becomes False and the loop never ends.'),
  (5, 'What does continue do?', '["Ends the loop","Skips the rest of this iteration and starts the next","Repeats the current iteration","Does nothing"]'::jsonb, 'Skips the rest of this iteration and starts the next', 'continue abandons the current pass through the loop and jumps straight to the next one.'),
  (6, 'What does numbers[0] return for numbers = [10, 20, 30]?', '["10","20","0","An error"]'::jsonb, '10', 'Python indexes from 0, so [0] is the first item. Expecting 20 here is a classic off-by-one mistake.'),
  (6, 'What does numbers[-1] return?', '["An error","The first item","The last item","Zero"]'::jsonb, 'The last item', 'Negative indexes count from the end, so -1 is the last item. It is the safe way to get the end without knowing the length.'),
  (6, 'What is the difference between append and extend?', '["No difference","append adds one item; extend adds each item of another list","extend is faster","append only works on numbers"]'::jsonb, 'append adds one item; extend adds each item of another list', 'append([1,2]) adds the list itself as one element. extend([1,2]) adds 1 and 2 separately.'),
  (6, 'What does numbers[1:3] return for [10, 20, 30, 40]?', '["[20, 30]","[10, 20, 30]","[20, 30, 40]","[10, 20]"]'::jsonb, '[20, 30]', 'Slicing includes the start index and excludes the end, so 1:3 gives positions 1 and 2.'),
  (6, 'Are lists mutable?', '["No, they are fixed once created","Yes, you can change items after creating them","Only if they hold numbers","Only inside a function"]'::jsonb, 'Yes, you can change items after creating them', 'Lists are mutable: you can add, remove and replace items in place. Tuples are the immutable equivalent.'),
  (7, 'What is the main difference between a tuple and a list?', '["Tuples hold only numbers","Tuples cannot be changed after creation","Tuples are always longer","There is no difference"]'::jsonb, 'Tuples cannot be changed after creation', 'A tuple is immutable. Use one when the data should not change - coordinates, or a fixed configuration.'),
  (7, 'What does a set automatically do?', '["Sorts the items","Removes duplicate values","Converts items to strings","Reverses the order"]'::jsonb, 'Removes duplicate values', 'A set stores unique values only. set([1,2,2,3]) becomes {1,2,3}, which makes it a quick way to deduplicate.'),
  (7, 'Which is the correct way to write a tuple with one item?', '["(5)","(5,)","[5]","{5}"]'::jsonb, '(5,)', 'Without the trailing comma, (5) is just the number 5 in brackets. The comma is what makes it a tuple.'),
  (7, 'Which operation is a set NOT good for?', '["Checking membership quickly","Removing duplicates","Keeping items in the order they were added","Finding items common to two collections"]'::jsonb, 'Keeping items in the order they were added', 'Sets are unordered. If insertion order matters, use a list.'),
  (7, 'What does {1,2,3} & {2,3,4} return?', '["{1,2,3,4}","{2,3}","{1,4}","An error"]'::jsonb, '{2,3}', '& is set intersection: the items present in both sets.'),
  (8, 'How do you safely read a key that might not exist?', '["d[''key'']","d.get(''key'')","d.find(''key'')","d.read(''key'')"]'::jsonb, 'd.get(''key'')', 'd[''missing''] raises a KeyError. d.get(''missing'') returns None instead, and you can supply a default.'),
  (8, 'What can be used as a dictionary key?', '["Only strings","Any immutable value such as a string, number or tuple","Any value at all, including lists","Only numbers"]'::jsonb, 'Any immutable value such as a string, number or tuple', 'Keys must be hashable, which in practice means immutable. A list cannot be a key; a tuple can.'),
  (8, 'What does d.items() give you?', '["Just the keys","Just the values","Key and value pairs","The number of entries"]'::jsonb, 'Key and value pairs', 'items() yields (key, value) pairs, which is why ''for k, v in d.items():'' is such a common loop.'),
  (8, 'What happens if you assign to a key that already exists?', '["It raises an error","It adds a second copy of the key","It replaces the existing value","It is ignored"]'::jsonb, 'It replaces the existing value', 'Keys are unique. Assigning to an existing key overwrites its value rather than adding a duplicate.'),
  (8, 'Which structure best models a student''s marks by subject?', '["A list of numbers","A dictionary mapping subject to mark","A set of marks","A single string"]'::jsonb, 'A dictionary mapping subject to mark', 'A dictionary links each subject to its mark, so you can look up ''maths'' directly instead of remembering a position.'),
  (9, 'What does a function return if it has no return statement?', '["0","An empty string","None","It raises an error"]'::jsonb, 'None', 'Every Python function returns something. Without an explicit return, that something is None.'),
  (9, 'What is a local variable?', '["A variable defined outside any function","A variable that exists only inside the function that created it","A variable that cannot change","A variable shared by every function"]'::jsonb, 'A variable that exists only inside the function that created it', 'Local variables live and die with the call. Trying to use one outside its function raises a NameError.'),
  (9, 'What are keyword arguments useful for?', '["Making the function run faster","Naming arguments at the call site so order does not matter","Declaring the return type","Forcing arguments to be strings"]'::jsonb, 'Naming arguments at the call site so order does not matter', 'greet(name=''Riya'', greeting=''Hi'') is clearer than greet(''Riya'', ''Hi'') and does not depend on argument order.'),
  (9, 'Why should a function usually do one thing?', '["Python enforces it","It runs faster","It is easier to name, test and reuse","It uses less memory"]'::jsonb, 'It is easier to name, test and reuse', 'A function you can name precisely is one you can test and reuse. If the name needs ''and'' in it, consider splitting it.'),
  (9, 'What does ''return'' do as soon as it runs?', '["Prints the value","Ends the function immediately and sends the value back","Stores the value in a global","Continues to the next line"]'::jsonb, 'Ends the function immediately and sends the value back', 'return exits the function on the spot. Any code after it in that function never runs.'),
  (10, 'What does ''import math'' give you?', '["Every function in Python","Access to the math module''s functions via math.something","A copy of the math source code","Faster arithmetic"]'::jsonb, 'Access to the math module''s functions via math.something', 'import makes the module available under its name, so you call math.sqrt(16) rather than just sqrt(16).'),
  (10, 'What does ''if __name__ == "__main__":'' protect against?', '["Syntax errors","Code running when the file is imported by another file","Slow imports","Missing modules"]'::jsonb, 'Code running when the file is imported by another file', 'Its value is ''__main__'' only when the file is run directly, so the guarded code does not fire on import.'),
  (10, 'What is the difference between a module and a package?', '["Nothing","A module is one file; a package is a folder of modules","A package is always third-party","A module must be installed with pip"]'::jsonb, 'A module is one file; a package is a folder of modules', 'A module is a single .py file. A package groups several modules in a directory.'),
  (10, 'What does ''from math import sqrt'' do?', '["Imports the whole math module","Brings sqrt into your file so you can call it directly","Renames math to sqrt","Raises an error"]'::jsonb, 'Brings sqrt into your file so you can call it directly', 'It pulls one name into your namespace. You then write sqrt(16) with no math. prefix.'),
  (10, 'Why avoid ''from module import *''?', '["It is slower","It can silently overwrite names you already defined","It only works for built-in modules","It breaks in Python 3"]'::jsonb, 'It can silently overwrite names you already defined', 'Wildcard imports make it impossible to see where a name came from, and can quietly shadow your own variables.'),
  (11, 'Why use ''with open(...) as f:'' instead of open() alone?', '["It is shorter to type","It closes the file automatically, even if an error happens","It makes reading faster","It allows two files at once"]'::jsonb, 'It closes the file automatically, even if an error happens', 'The context manager guarantees the file is closed. Without it, an exception can leave the file handle open.'),
  (11, 'What does opening a file in ''w'' mode do to an existing file?', '["Appends to the end","Erases its contents","Raises an error","Opens it read-only"]'::jsonb, 'Erases its contents', '''w'' truncates the file to zero length. Use ''a'' to add to the end without destroying what is there.'),
  (11, 'Which mode adds to the end of a file?', '["''r''","''w''","''a''","''x''"]'::jsonb, '''a''', '''a'' is append mode: writes go to the end and existing content is preserved.'),
  (11, 'What does f.readlines() return?', '["One long string","A list of lines","The number of lines","The first line only"]'::jsonb, 'A list of lines', 'readlines() gives a list with one element per line. read() gives the whole file as a single string.'),
  (11, 'What error occurs when opening a file that does not exist in ''r'' mode?', '["ValueError","FileNotFoundError","IOError only in Python 2","It creates the file"]'::jsonb, 'FileNotFoundError', 'Reading a missing file raises FileNotFoundError, which is why file work is usually wrapped in try/except.'),
  (12, 'What does the finally block do?', '["Runs only when there is no error","Runs only when there is an error","Runs either way, error or not","Cancels the exception"]'::jsonb, 'Runs either way, error or not', 'finally always runs, which makes it the right place for cleanup such as closing a connection.'),
  (12, 'Why is ''except Exception:'' better than a bare ''except:''?', '["It is faster","A bare except also catches Ctrl+C and system exits","There is no difference","Bare except is a syntax error"]'::jsonb, 'A bare except also catches Ctrl+C and system exits', 'A bare except swallows KeyboardInterrupt and SystemExit too, which can make a program impossible to stop.'),
  (12, 'What is the point of catching a specific exception type?', '["It looks more professional","You only handle the failure you expected, and real bugs still surface","It runs faster","Python requires it"]'::jsonb, 'You only handle the failure you expected, and real bugs still surface', 'Catching everything hides genuine bugs. Catching ValueError means a typo elsewhere still raises loudly.'),
  (12, 'When does the else block of a try run?', '["Always","Only if an exception was raised","Only if no exception was raised","Never"]'::jsonb, 'Only if no exception was raised', 'try/except/else: the else runs when the try body succeeded, keeping the risky lines and the follow-up separate.'),
  (12, 'What does ''raise'' do?', '["Catches an exception","Deliberately triggers an exception","Logs a warning","Restarts the program"]'::jsonb, 'Deliberately triggers an exception', 'raise signals a problem your code has detected, such as an invalid argument, so the caller can handle it.'),
  (13, 'What does __init__ do?', '["Destroys the object","Runs when a new object is created, to set it up","Imports the class","Prints the object"]'::jsonb, 'Runs when a new object is created, to set it up', '__init__ is the constructor. It receives the new object as self and gives its attributes their starting values.'),
  (13, 'What is ''self'' in a method?', '["The class itself","The particular object the method was called on","A reserved Python keyword","The parent class"]'::jsonb, 'The particular object the method was called on', 'self is the instance. It is how one object''s data stays separate from another''s, and it is passed automatically.'),
  (13, 'What is the difference between a class and an object?', '["They are the same","A class is the blueprint; an object is one thing built from it","An object is the blueprint","A class can only be used once"]'::jsonb, 'A class is the blueprint; an object is one thing built from it', 'Class Student describes what a student has and does. riya = Student() creates one actual student.'),
  (13, 'Where do instance attributes usually get their initial values?', '["In the class body","Inside __init__","In a separate setup() call","They cannot be initialised"]'::jsonb, 'Inside __init__', 'Assigning self.name inside __init__ gives every new object its own copy of that attribute.'),
  (13, 'What happens if you forget self in a method definition?', '["Nothing","Python adds it automatically","Calling it on an object raises a TypeError about arguments","The method becomes private"]'::jsonb, 'Calling it on an object raises a TypeError about arguments', 'Python passes the instance as the first argument, so a method without self gets one argument more than it declared.'),
  (14, 'What does a subclass inherit from its parent?', '["Only the attributes","Only the methods","Both attributes and methods","Nothing automatically"]'::jsonb, 'Both attributes and methods', 'A subclass starts with everything the parent has, and adds or overrides only what differs.'),
  (14, 'What does super().__init__() do?', '["Creates a new parent object","Runs the parent''s setup so inherited attributes exist","Deletes the parent class","Is optional and has no effect"]'::jsonb, 'Runs the parent''s setup so inherited attributes exist', 'Without it, attributes the parent''s __init__ would have created simply do not exist on your object.'),
  (14, 'What is method overriding?', '["Calling a method twice","Defining a method in the subclass with the same name as the parent''s","Deleting a parent method","Renaming a method"]'::jsonb, 'Defining a method in the subclass with the same name as the parent''s', 'The subclass version replaces the parent''s for objects of that subclass, letting you specialise behaviour.'),
  (14, 'When is inheritance the wrong tool?', '["When the subclass genuinely is a kind of the parent","When you only want to reuse one convenient method","When you need to override a method","When the classes share attributes"]'::jsonb, 'When you only want to reuse one convenient method', 'Inheritance means ''is a''. If you only want a helper, composition - holding an instance - is clearer.'),
  (14, 'Can a class inherit from more than one parent in Python?', '["No, never","Yes, Python supports multiple inheritance","Only for built-in classes","Only two levels deep"]'::jsonb, 'Yes, Python supports multiple inheritance', 'Python allows it, though it should be used carefully because the method resolution order gets hard to follow.'),
  (15, 'What does polymorphism let you do?', '["Store more data in one object","Call the same method name on different types and get behaviour suited to each","Convert between data types","Inherit from two classes"]'::jsonb, 'Call the same method name on different types and get behaviour suited to each', 'Calling .area() on a Circle and a Square works for both, and each computes it its own way.'),
  (15, 'What is duck typing?', '["Checking a type with isinstance before every call","If an object has the method you need, its exact class does not matter","Converting all objects to a common class","A way of copying objects"]'::jsonb, 'If an object has the method you need, its exact class does not matter', 'Python cares that the object supports the operation, not what it inherits from - ''if it walks like a duck''.'),
  (15, 'Why does polymorphism reduce if/elif chains?', '["It makes conditions run faster","Each type carries its own behaviour, so no branching on type is needed","It removes the need for functions","It caches the result"]'::jsonb, 'Each type carries its own behaviour, so no branching on type is needed', 'Instead of checking what kind of shape it is, you just call .area() and let the object decide.'),
  (15, 'What must be true for two classes to be used interchangeably?', '["They must share a parent class","They must expose the methods the calling code uses","They must have the same attributes","They must be in the same file"]'::jsonb, 'They must expose the methods the calling code uses', 'In Python the shared interface matters, not the family tree. A common parent is one way to get there, not the only way.'),
  (15, 'What does len() demonstrate about polymorphism?', '["It only works on lists","It behaves sensibly for strings, lists, dicts and more","It is faster than a loop","It requires inheritance"]'::jsonb, 'It behaves sensibly for strings, lists, dicts and more', 'len() works on anything defining __len__, which is polymorphism built into the language.'),
  (16, 'What does encapsulation mean?', '["Making every attribute public","Keeping internal state behind a controlled interface","Combining two classes","Copying an object"]'::jsonb, 'Keeping internal state behind a controlled interface', 'The object owns its data and exposes only what callers need, so internals can change without breaking them.'),
  (16, 'What does a leading underscore, as in _balance, signal?', '["Python makes it private and inaccessible","It is a convention meaning ''internal, do not touch''","It is a syntax error","It makes the attribute read-only"]'::jsonb, 'It is a convention meaning ''internal, do not touch''', 'Python does not enforce privacy. The underscore is a message to other developers, honoured by convention.'),
  (16, 'What does the @property decorator let you do?', '["Make a method run faster","Access a method like an attribute, with logic behind it","Delete an attribute","Make a class abstract"]'::jsonb, 'Access a method like an attribute, with logic behind it', 'You can start with a plain attribute and later turn it into a property with validation, without changing caller code.'),
  (16, 'What is abstraction?', '["Hiding how something works behind a simple interface","Removing all methods","Writing shorter variable names","Making a class inherit from object"]'::jsonb, 'Hiding how something works behind a simple interface', 'A car''s pedal is an abstraction: you press it without knowing about fuel injection. Good classes work the same way.'),
  (16, 'Why is exposing every attribute publicly risky?', '["It uses more memory","Callers depend on internals, so you cannot change them later","Python runs slower","It prevents inheritance"]'::jsonb, 'Callers depend on internals, so you cannot change them later', 'Once outside code reads obj.total directly, changing how total is stored breaks that code.'),
  (17, 'What belongs in a project README?', '["The full source code","What the project does and how to run it","Only the author''s name","A list of every variable"]'::jsonb, 'What the project does and how to run it', 'A README exists so somebody else can run your project. What it does, how to install, how to start it.'),
  (17, 'Why put a project under version control?', '["It makes it run faster","It records history so you can see and undo changes","It is required by Python","It compresses the files"]'::jsonb, 'It records history so you can see and undo changes', 'Git lets you experiment safely, because any change can be inspected and reverted.'),
  (17, 'What should never be committed to a repository?', '["The README","Test files","API keys and passwords","The requirements file"]'::jsonb, 'API keys and passwords', 'Secrets in a repo are exposed to anyone with access, and stay in the history even after deletion.'),
  (17, 'What makes a good capstone project?', '["Using every feature of Python","Solving one real problem end to end","Being the longest program you can write","Avoiding external libraries"]'::jsonb, 'Solving one real problem end to end', 'A small project that genuinely works beats a large one that half works. Scope it so you can finish.'),
  (17, 'Why does a .gitignore matter?', '["It speeds up Python","It keeps environments, caches and secrets out of the repository","It documents the project","It is required by pip"]'::jsonb, 'It keeps environments, caches and secrets out of the repository', 'Without it you commit your venv folder and possibly your .env file, which is both noisy and unsafe.'),
  (18, 'What does [m for m in marks if m >= 50] produce?', '["Every mark","Only the marks of 50 or more","The count of passing marks","A single boolean"]'::jsonb, 'Only the marks of 50 or more', 'The condition filters, so only items satisfying it are collected into the new list.'),
  (18, 'What is the main limitation of a lambda?', '["It cannot take arguments","It can only contain a single expression","It cannot be assigned to a variable","It runs slower than def"]'::jsonb, 'It can only contain a single expression', 'A lambda has no statements - no if blocks, no loops, no return. One expression, whose value it returns.'),
  (18, 'Where is a lambda genuinely useful?', '["Replacing every def in your code","As the key argument to sorted, min or max","For long multi-step calculations","For recursive functions"]'::jsonb, 'As the key argument to sorted, min or max', 'sorted(data, key=lambda x: x[1]) is clear and local. Anything longer reads better as a named function.'),
  (18, 'What does a dictionary comprehension build?', '["A list of tuples","Key and value pairs in one expression","A set","A generator"]'::jsonb, 'Key and value pairs in one expression', '{n: s for n, s in zip(names, scores)} builds a whole dictionary in a single readable line.'),
  (18, 'When should you use a normal loop instead of a comprehension?', '["Never, comprehensions are always better","When the logic needs several conditions or nesting and readability suffers","When the list is long","When working with strings"]'::jsonb, 'When the logic needs several conditions or nesting and readability suffers', 'If you have to pause to parse your own comprehension, the loop it replaced was the clearer code.'),
  (19, 'What makes a function a generator function?', '["It returns a list","It contains the yield keyword","It is decorated","It takes no arguments"]'::jsonb, 'It contains the yield keyword', 'Any function containing yield returns a generator when called, instead of running to completion.'),
  (19, 'What is the main advantage of a generator over a list?', '["It is easier to read","It produces values on demand, so memory stays small","It can be indexed","It can be reused many times"]'::jsonb, 'It produces values on demand, so memory stays small', 'A generator never holds all values at once, which is what makes processing huge files practical.'),
  (19, 'What happens when you loop over the same generator twice?', '["You get the same values again","The second loop produces nothing because it is exhausted","It raises an error","It restarts automatically"]'::jsonb, 'The second loop produces nothing because it is exhausted', 'A generator is consumed by one pass. If you need the data again, collect it into a list first.'),
  (19, 'What does next() raise when a generator is finished?', '["ValueError","StopIteration","IndexError","None"]'::jsonb, 'StopIteration', 'StopIteration signals the end. A for loop catches it for you, which is why you rarely see it.'),
  (19, 'How does a generator expression differ from a list comprehension?', '["It uses round brackets and is lazy","It is always faster","It can only hold numbers","There is no difference"]'::jsonb, 'It uses round brackets and is lazy', '(x*x for x in range(10)) produces values as requested; [x*x for x in range(10)] builds them all immediately.'),
  (20, 'What does a decorator actually do?', '["Renames a function","Takes a function and returns a replacement, usually a wrapper","Makes a function private","Deletes the original function"]'::jsonb, 'Takes a function and returns a replacement, usually a wrapper', '@log above a def is shorthand for func = log(func). Whatever log returns takes the original''s name.'),
  (20, 'Why do wrappers use *args and **kwargs?', '["To make them faster","So the decorator works on functions with any signature","Python requires it","To avoid returning a value"]'::jsonb, 'So the decorator works on functions with any signature', 'Without them the wrapper only fits functions with one exact argument list, and the decorator is not reusable.'),
  (20, 'What does functools.wraps preserve?', '["The function''s speed","The original name and docstring","The function''s arguments","The return value"]'::jsonb, 'The original name and docstring', 'Without it, every decorated function reports itself as ''wrapper'' in tracebacks and help(), which makes debugging harder.'),
  (20, 'What is a higher-order function?', '["A function defined at the top of a file","One that takes or returns another function","A function with many arguments","A recursive function"]'::jsonb, 'One that takes or returns another function', 'sorted is one: it accepts a key function. Decorators are another, returning a function.'),
  (20, 'Where will you commonly meet decorators?', '["Only in tutorials","In web frameworks for routing and in test libraries","Only in the standard library","In file handling"]'::jsonb, 'In web frameworks for routing and in test libraries', 'Flask uses @app.route to attach a URL to a function; pytest and unittest use them to mark tests.'),
  (21, 'What is the difference between re.match and re.search?', '["No difference","match only checks the start of the string; search looks anywhere","search is faster","match returns a list"]'::jsonb, 'match only checks the start of the string; search looks anywhere', 'Using match when you meant search is the most common early regex mistake - it silently finds nothing.'),
  (21, 'What does \d match?', '["Any letter","Any digit","Any whitespace","Any character"]'::jsonb, 'Any digit', '\d matches a single digit 0-9. \w matches a letter, digit or underscore.'),
  (21, 'What does the + quantifier mean?', '["Exactly one","Zero or more","One or more","Optional"]'::jsonb, 'One or more', '+ requires at least one occurrence. * allows zero or more, and ? makes something optional.'),
  (21, 'What do round brackets create in a pattern?', '["A comment","A capturing group you can extract","An optional section","A character class"]'::jsonb, 'A capturing group you can extract', 'Groups let you pull out parts of a match, such as splitting a date into day, month and year.'),
  (21, 'When is a regular expression the wrong tool?', '["Validating a phone number","Finding digits in text","Parsing HTML or JSON","Replacing whitespace"]'::jsonb, 'Parsing HTML or JSON', 'Structured formats have proper parsers. A regex for HTML breaks on the first edge case.'),
  (22, 'Why store a date as a datetime rather than a string?', '["It uses less memory","Comparison and arithmetic work correctly, including month lengths","Strings cannot hold dates","It prints more nicely"]'::jsonb, 'Comparison and arithmetic work correctly, including month lengths', 'Subtracting two datetimes gives a real difference. Subtracting two strings is not possible at all.'),
  (22, 'What does strftime do?', '["Parses text into a date","Formats a datetime into text","Adds days to a date","Returns the current time"]'::jsonb, 'Formats a datetime into text', 'strftime formats out; strptime parses in. The p in strptime stands for parse.'),
  (22, 'What does subtracting one datetime from another produce?', '["An integer of seconds","A timedelta","A string","An error"]'::jsonb, 'A timedelta', 'A timedelta reports the gap in days and seconds, and can be added to a date to move it.'),
  (22, 'How would you calculate a deadline ten days from now?', '["now + 10","now + timedelta(days=10)","now.add(10)","now * 10"]'::jsonb, 'now + timedelta(days=10)', 'timedelta is the correct way to shift a datetime, and it handles month and year boundaries for you.'),
  (22, 'What does strptime do if the text does not match the format?', '["Returns None","Guesses the closest date","Raises a ValueError","Returns today''s date"]'::jsonb, 'Raises a ValueError', 'The error is useful: it makes strptime a practical way to validate a date the user typed.'),
  (23, 'What does json.loads do?', '["Writes JSON to a file","Turns JSON text into Python objects","Turns Python objects into JSON text","Downloads JSON from a URL"]'::jsonb, 'Turns JSON text into Python objects', 'loads means ''load string''. dumps goes the other way. The s in both stands for string.'),
  (23, 'What does an HTTP status of 200 mean?', '["Not found","Success","Server error","Redirect"]'::jsonb, 'Success', '200 is success, 404 is not found and 500 is a server error. Check the code before trusting the body.'),
  (23, 'Why should you always pass a timeout to a request?', '["It makes the request faster","Without one your program can hang indefinitely","The server requires it","It reduces data usage"]'::jsonb, 'Without one your program can hang indefinitely', 'A server that never responds will otherwise block your program forever with no error.'),
  (23, 'Where should an API key be stored?', '["In the source code","In an environment variable read at runtime","In a comment","In the README"]'::jsonb, 'In an environment variable read at runtime', 'A key in source ends up in version control, visible to anyone with repository access, and stays in the history.'),
  (23, 'What should you do before using response.json()?', '["Nothing, it is always safe","Check the status code and handle the case where the body is not JSON","Convert it to a string","Sleep for one second"]'::jsonb, 'Check the status code and handle the case where the body is not JSON', 'An error page is usually HTML, so calling .json() on it raises. Check the status first and wrap it in try/except.'),
  (24, 'Why use question-mark placeholders in an SQL query?', '["They run faster","They stop user input being executed as SQL","They are easier to read","SQLite requires them"]'::jsonb, 'They stop user input being executed as SQL', 'Joining strings lets a user type their own SQL. Placeholders pass values as data, which the library escapes.'),
  (24, 'What must you call after INSERT, UPDATE or DELETE?', '["close()","commit()","flush()","Nothing"]'::jsonb, 'commit()', 'Without commit() the changes are lost when the connection closes.'),
  (24, 'What does a primary key do?', '["Sorts the table","Uniquely identifies each row","Encrypts the data","Speeds up writes"]'::jsonb, 'Uniquely identifies each row', 'It guarantees no two rows share the same identifier, which is what lets other tables reference a row reliably.'),
  (24, 'What is a foreign key for?', '["Encrypting a column","Pointing at a row in another table","Making a column unique","Setting a default value"]'::jsonb, 'Pointing at a row in another table', 'It links tables - a marks row referring to a students row - so a student''s name is stored once, not repeated.'),
  (24, 'Why is SQLite convenient for learning?', '["It is faster than every other database","It is built into Python and needs no server","It has no SQL syntax","It only stores text"]'::jsonb, 'It is built into Python and needs no server', 'The whole database is one file and the module ships with Python, so there is nothing to install or run.'),
  (25, 'Where is the most useful information in a traceback?', '["The first line","The last line, which names the error","The middle","The file size"]'::jsonb, 'The last line, which names the error', 'Read from the bottom: the final line states what went wrong, and the lines above show how the code got there.'),
  (25, 'What does assert do?', '["Prints a value","Raises an error if the condition is False","Stops the program unconditionally","Logs a message"]'::jsonb, 'Raises an error if the condition is False', 'assert is the building block of a test: state what should be true and let it fail loudly if it is not.'),
  (25, 'Why write a test for an empty list?', '["To make the test count higher","Edge cases like empty input are where bugs hide","Python requires it","Empty lists are slow"]'::jsonb, 'Edge cases like empty input are where bugs hide', 'An average function that divides by len(marks) crashes on an empty list. The test forces you to decide what should happen.'),
  (25, 'What is the advantage of logging over print for debugging?', '["It is faster","Messages can be left in and switched on or off by level","It prints in colour","It works without imports"]'::jsonb, 'Messages can be left in and switched on or off by level', 'With print you add and delete lines repeatedly. With logging you set the level and keep the messages.'),
  (25, 'What is the right way to approach a bug?', '["Change several things and see if it goes away","Reproduce it, shrink the code, form one hypothesis and test it","Rewrite the function from scratch","Add try/except around it"]'::jsonb, 'Reproduce it, shrink the code, form one hypothesis and test it', 'Changing several things at once hides which change mattered. One hypothesis at a time is faster in practice.'),
  (26, 'What problem does a virtual environment solve?', '["Slow code","Two projects needing different versions of the same package","Syntax errors","Large file sizes"]'::jsonb, 'Two projects needing different versions of the same package', 'Each project gets its own packages, so upgrading a library for one cannot break another.'),
  (26, 'What does pip freeze produce?', '["A list of installed packages with exact versions","A compiled program","A new virtual environment","A backup of your code"]'::jsonb, 'A list of installed packages with exact versions', 'Redirected into requirements.txt, it lets someone else reproduce your exact setup.'),
  (26, 'How does someone else install your project''s dependencies?', '["pip install requirements.txt","pip install -r requirements.txt","python requirements.txt","pip freeze requirements.txt"]'::jsonb, 'pip install -r requirements.txt', 'The -r flag tells pip to read the file as a list of requirements rather than treat it as a package name.'),
  (26, 'Why should the venv folder never be committed?', '["It is very large and machine-specific","It contains your source code","Git cannot store it","It is encrypted"]'::jsonb, 'It is very large and machine-specific', 'It holds installed binaries for one operating system. requirements.txt records what is needed in a few lines instead.'),
  (26, 'What makes a project easy for someone else to run?', '["Clever one-line code","A README with setup steps, a requirements file and no hardcoded paths","Lots of comments","Being written in one file"]'::jsonb, 'A README with setup steps, a requirements file and no hardcoded paths', 'A project someone can start in two commands is far more useful than one that only runs on your laptop.');
